#!/usr/bin/env bash
# MobaXterm convenience wrapper. All traffic is generated by k6 scenarios.js.
# Usage: bash cloud-insight-quick-load.sh http://SERVER_IP:8080
set -euo pipefail

base_url="${1:-${BASE_URL:-}}"
base_url="${base_url%/}"
k6_bin="${K6_BIN:-k6}"
script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
k6_script="$script_dir/k6/scenarios.js"

if [[ ! "$base_url" =~ ^https?:// ]]; then
  echo "Usage: bash $0 http://SERVER_IP:8080" >&2
  exit 2
fi
if ! command -v "$k6_bin" >/dev/null 2>&1 &&
    [[ "$k6_bin" == k6 && -x '/drives/c/Program Files/k6/k6.exe' ]]; then
  k6_bin='/drives/c/Program Files/k6/k6.exe'
fi
if ! command -v "$k6_bin" >/dev/null 2>&1; then
  echo "k6 is required. Install it or set K6_BIN to its executable path." >&2
  exit 2
fi
if [[ ! -f "$k6_script" ]]; then
  echo "Missing k6 script: $k6_script" >&2
  echo "Copy the k6/ directory alongside this wrapper." >&2
  exit 2
fi

exec "$k6_bin" run \
  -e PROFILE=lt18 \
  -e BASE_URL="$base_url" \
  -e AUTH_MODE="${AUTH_MODE:-TOKEN}" \
  -e STUDENT_ID="${STUDENT_ID:-1}" \
  -e STUDENT_NO="${STUDENT_NO:-2024000001}" \
  -e STUDENT_PASSWORD="${STUDENT_PASSWORD:-${STUDENT_NO:-2024000001}}" \
  -e HOT_OFFERING_ID="${HOT_OFFERING_ID:-9}" \
  -e BASELINE_VUS="${BASELINE_VUS:-1}" \
  -e SPIKE_VUS="${SPIKE_VUS:-32}" \
  -e BASELINE_DURATION="${BASELINE_DURATION:-90s}" \
  -e SPIKE_DURATION="${SPIKE_DURATION:-180s}" \
  -e RECOVERY_DURATION="${RECOVERY_DURATION:-90s}" \
  -e THINK_TIME="${THINK_TIME:-1}" \
  "$k6_script"
